/* Customer master and one-to-many contracts, using server-side scope and version checks. */
'use strict';
const ContractNames={VALID:'有效期内',UPCOMING:'尚未生效',EXPIRED:'已到期',INACTIVE:'已停用'};
Object.assign(Business,{
 async customers(){const d=await this.load(),q=new URLSearchParams(location.search),r=await API.request('/contracts?'+q);this.open('客户管理',`<div class="business-toolbar"><button id="customer-new" class="button primary" ${this.can('customer:write')?'':'disabled'}>新增客户</button><button id="contract-new" class="button secondary" ${this.can('customer:write')?'':'disabled'}>新增合同</button>${this.can('master:write')?'<a class="button secondary" href="/customers/master-data">生产批次、仓库与货位资料</a>':''}</div><form id="contract-filter" class="business-toolbar"><label>搜索合同号 / 客户<input name="search" value="${esc(q.get('search')||'')}"></label><label>有效期状态<select name="validity"><option value="">全部</option>${Object.entries(ContractNames).map(([k,v])=>`<option value="${k}" ${q.get('validity')===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button secondary">筛选</button></form><h3>客户档案</h3><div class="business-table"><table><thead><tr><th>客户编码</th><th>客户名称</th><th>状态</th><th>操作</th></tr></thead><tbody>${d.customers.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.name)}</td><td>${c.active?'启用':'停用'}</td><td><button data-customer-edit="${c.id}" class="detail-button" ${this.can('customer:write')?'':'disabled'}>编辑 / 启停</button></td></tr>`).join('')}</tbody></table></div><h3>合同档案（一客户多合同）</h3><p>新计划与新备货必须使用有效合同；合同号与客户关系建立后不可替换。到期、停用不删除既有业务历史。</p><div class="business-table"><table><thead><tr><th>合同号</th><th>客户名称</th><th>生效日期</th><th>截止日期</th><th>启停状态</th><th>有效期状态</th><th>操作</th></tr></thead><tbody>${r.items.map(k=>`<tr><td>${esc(k.contract_no)}</td><td>${esc(k.customer_name)}</td><td>${esc(k.effective_date)}</td><td>${esc(k.end_date)}</td><td>${k.active?'启用':'停用'}</td><td>${esc(ContractNames[k.validity])}</td><td><a href="/customers/contracts/${k.id}">查看</a> <button class="detail-button" data-contract-edit="${k.id}" ${this.can('customer:write')?'':'disabled'}>编辑 / 启停</button></td></tr>`).join('')||'<tr><td colspan="7">暂无匹配合同；历史计划未自动关联合同。</td></tr>'}</tbody></table></div>`);$('customer-new').onclick=()=>this.masterForm('customers');$('contract-new').onclick=()=>this.contractForm();document.querySelectorAll('[data-customer-edit]').forEach(b=>b.onclick=()=>this.masterForm('customers',d.customers.find(c=>c.id===b.dataset.customerEdit)));document.querySelectorAll('[data-contract-edit]').forEach(b=>b.onclick=()=>this.contractForm(r.items.find(k=>k.id===b.dataset.contractEdit)));$('contract-filter').onsubmit=e=>{e.preventDefault();Router.go('/customers?'+new URLSearchParams(new FormData(e.target)));};},
 async contractForm(k={}){const d=await this.load();this.open(k.id?'编辑合同':'新增客户合同',`<form class="user-form" id="contract-form"><div class="form-grid"><label>项目<select name="project_id" ${k.id?'disabled':''}>${this.options(d.projects,k.project_id,'name')}</select></label><label>客户名称<select name="customer_id" ${k.id?'disabled':''}>${this.options(d.customers,k.customer_id,'name')}</select></label><label>合同号<input name="contract_no" required maxlength="80" value="${esc(k.contract_no||'')}" ${k.id?'readonly':''}></label><label>合同生效日期<input name="effective_date" type="date" required value="${esc(k.effective_date||'')}"></label><label>合同截止日期<input name="end_date" type="date" required value="${esc(k.end_date||'')}"></label><label>启停状态<select name="active"><option value="true">启用</option><option value="false" ${k.active===false?'selected':''}>停用</option></select></label></div><p>有效期按刚果金业务日期（Africa/Lubumbashi）由服务器判定。停用或到期后不能新增备货，历史记录继续保留。</p><p class="error" id="contract-error" role="alert"></p><button class="button primary">保存合同</button></form>`);$('contract-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));body.active=body.active==='true';if(k.id)body.version=k.version;const r=await API.request('/contracts'+(k.id?'/'+k.id:''),{method:k.id?'PATCH':'POST',body});await this.contractDetail(r.id);notify('合同已保存');}catch(err){$('contract-error').textContent=err.message;e.submitter.disabled=false;}};},
 async contractDetail(id){const k=await API.request('/contracts/'+id);this.open('合同 · '+k.contract_no,`<dl>${[['客户名称',k.customer_name],['合同号',k.contract_no],['合同生效日期',k.effective_date],['合同截止日期',k.end_date],['启停状态',k.active?'启用':'停用'],['有效期状态',ContractNames[k.validity]],['版本',k.version]].map(([l,v])=>`<dt>${esc(l)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${this.can('customer:write')?'<button id="contract-edit" class="button primary">编辑 / 启停</button>':''}<a class="button secondary" href="/customers">返回客户管理</a>`);if($('contract-edit'))$('contract-edit').onclick=()=>this.contractForm(k);}
});
